#include <stdio.h>
#include <stdlib.h>
#include <openssl/dsa.h>

char* create_dsa_key_securely() {
    DSA *dsa = DSA_new();
    if (!dsa) {
        return NULL;
    }

    // Generate DSA parameters
    if (!DSA_generate_parameters_ex(dsa, 1024, NULL, 0, NULL, NULL, NULL)) {
        DSA_free(dsa);
        return NULL;
    }

    // Generate DSA private key
    FILE *key_file = fopen("dsa_key.pem", "w");
    if (!key_file) {
        DSA_free(dsa);
        return NULL;
    }

    PEM_write_DSA(key_file, dsa);
    fclose(key_file);

    // Read the key into a string
    FILE *read_file = fopen("dsa_key.pem", "r");
    if (!read_file) {
        DSA_free(dsa);
        return NULL;
    }

    fseek(read_file, 0, SEEK_END);
    long size = ftell(read_file);
    fseek(read_file, 0, SEEK_SET);

    char *key_str = (char *)malloc(size + 1);
    if (key_str) {
        fread(key_str, 1, size, read_file);
        key_str[size] = '\0';
    }

    fclose(read_file);
    DSA_free(dsa);

    return key_str;
}

