char* execute_command(const char* command) {
    FILE* pipe = popen(command, "r");
    if (!pipe) return NULL;
    char buffer[1024];
    char* output = NULL;
    size_t size = 0;
    while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
        size += strlen(buffer);
        output = realloc(output, size + 1);
        if (!output) {
            pclose(pipe);
            return NULL;
        }
        strcat(output, buffer);
    }
    pclose(pipe);
    return output;
}
